insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('4083a286-805f-4145-826c-60844390fcb7', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Trong phạm vi.../Ở mức độ... (giới hạn phạm vi thông tin/hiểu biết của người nói)"?', 'Nの／Vる・Vた／Vている ＋ 限り(では)', 'N に限り、.../N に限る。', 'Aい／V(普)／Aな・である／Nである ＋ 限り(は)', 'N ＋ に限って', 'Nの／Vる・Vた／Vている ＋ 限り(では)', 'generated');
