insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('8e628b6e-6c0f-4f1c-ac15-ab9ec6acac8a', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Trong lúc.../Khi... (chừng nào điều kiện đó còn đúng)"?', 'Aい／V(普)／Aな・である／Nである ＋ 限り(は)', 'Vようか Vるまいか', 'Vる・ない／N ＋ に限る', 'Vる(II:Vます・する→すまい・来る→来まい) ＋ まい', 'Aい／V(普)／Aな・である／Nである ＋ 限り(は)', 'generated');
